insert into public.questions
  (id, module, domain, skill, difficulty, passage, prompt, choices, answer, explanation)
values
  ($q$pd-571$q$, $q$math$q$, $q$Problem-Solving and Data Analysis$q$, $q$Percentages$q$, 1, null, $q$The price of a jacket decreased from $78 to $60. By what percent did the price decrease? (Round to the nearest whole percent.)$q$, $q$["33%","18%","23%","30%"]$q$::jsonb, 2, $q$Percent change = |60 − 78| / 78 × 100 = 18/78 × 100 ≈ 23%.$q$),
  ($q$pd-572$q$, $q$math$q$, $q$Problem-Solving and Data Analysis$q$, $q$Conditional probability$q$, 2, null, $q$Of 200 customers surveyed, 50 are customers who bought a phone. Of those 50, 20 also bought a case. If one of the customers who bought a phone is chosen at random, what is the probability that the person also bought a case?$q$, $q$["1/4","3/5","2/5","1/10"]$q$::jsonb, 2, $q$Restricted to the 50 customers who bought a phone, 20 also bought a case. The probability is 20/50 = 2/5.$q$),
  ($q$pd-573$q$, $q$math$q$, $q$Problem-Solving and Data Analysis$q$, $q$Rates and units$q$, 2, null, $q$A cyclist travels at a constant speed of 45 miles per hour. At this rate, how many feet does the cyclist travel in 1 second? (1 mile = 5,280 feet)$q$, $q$["3960","237600","132","66"]$q$::jsonb, 3, $q$45 miles per hour = 45 × 5,280 feet per 3,600 seconds = 66 feet per second.$q$),
  ($q$pd-574$q$, $q$math$q$, $q$Problem-Solving and Data Analysis$q$, $q$Probability$q$, 2, null, $q$The probability that a certain event occurs on any given day is 2/3, independent of other days. What is the probability that the event occurs on at least one of two consecutive days?$q$, $q$["1/3","8/9","4/3","4/9"]$q$::jsonb, 1, $q$The event fails both days with probability ((1)/3)² = 1/9. So P(at least one) = 1 − 1/9 = 8/9.$q$),
  ($q$pd-575$q$, $q$math$q$, $q$Problem-Solving and Data Analysis$q$, $q$Probability$q$, 2, null, $q$The probability that a certain event occurs on any given day is 1/2, independent of other days. What is the probability that the event occurs on at least one of two consecutive days?$q$, $q$["3/4","1/4","1/2","1"]$q$::jsonb, 0, $q$The event fails both days with probability ((1)/2)² = 1/4. So P(at least one) = 1 − 1/4 = 3/4.$q$),
  ($q$pd-576$q$, $q$math$q$, $q$Problem-Solving and Data Analysis$q$, $q$Two-variable data$q$, 2, null, $q$A model predicts y = 4x + 12. For x = 4, the actual observed value is 22. What is the residual (actual value minus predicted value) at x = 4?$q$, $q$["−6","22","28","6"]$q$::jsonb, 0, $q$Predicted value: 4(4) + 12 = 28. Residual = 22 − 28 = −6.$q$),
  ($q$pd-577$q$, $q$math$q$, $q$Problem-Solving and Data Analysis$q$, $q$One-variable data$q$, 1, null, $q$What is the range of the data set 28, 15, 25, 27, 24, 9?$q$, $q$["19","17","21","9"]$q$::jsonb, 0, $q$Range = largest − smallest = 28 − 9 = 19.$q$),
  ($q$pd-578$q$, $q$math$q$, $q$Problem-Solving and Data Analysis$q$, $q$Inference from sample statistics$q$, 2, null, $q$A poll of a random sample of voters estimated that 58% support a proposal, with a margin of error of 4 percentage points. Which of the following is the most plausible range for the percent of all voters who support the proposal?$q$, $q$["54% to 62%","58% to 66%","50% to 58%","56% to 60%"]$q$::jsonb, 0, $q$The plausible range is the estimate plus or minus the margin of error: 54% to 62%.$q$),
  ($q$pd-579$q$, $q$math$q$, $q$Problem-Solving and Data Analysis$q$, $q$Ratios and proportions$q$, 1, null, $q$On a map, 1 inch represents 10 miles. Two towns are 8 inches apart on the map. How many miles apart are the actual towns?$q$, $q$["80","40","90","1"]$q$::jsonb, 0, $q$Actual distance = 8 × 10 = 80 miles.$q$),
  ($q$pd-580$q$, $q$math$q$, $q$Problem-Solving and Data Analysis$q$, $q$Ratios and proportions$q$, 1, null, $q$The ratio of red marbles to blue marbles in a bag is 5:9. If the bag contains 56 marbles in total, how many are red?$q$, $q$["36","20","51","25"]$q$::jsonb, 1, $q$There are 14 parts in total, so each part is 56/14 = 4 marbles. Red: 5 × 4 = 20.$q$),
  ($q$pd-581$q$, $q$math$q$, $q$Problem-Solving and Data Analysis$q$, $q$One-variable data$q$, 2, null, $q$The mean of 6 test scores is 76. After one more test score is added, the mean of all 7 scores is 78. What is the score that was added?$q$, $q$["96","78","90","83"]$q$::jsonb, 2, $q$The new total is 7 × 78 = 546; the old total was 6 × 76 = 456. The added score is 546 − 456 = 90.$q$),
  ($q$pd-582$q$, $q$math$q$, $q$Problem-Solving and Data Analysis$q$, $q$Evaluating statistical claims$q$, 2, null, $q$A researcher surveyed a random sample of 300 adult residents selected from county voter and driver records. Which of the following is the largest population to which the results can reasonably be generalized?$q$, $q$["All people in the same state","All adult residents of Maple County","Only the people who were surveyed","All people who use social media"]$q$::jsonb, 1, $q$Random sampling from a list of all adult residents of Maple County supports generalizing to that group, but not beyond it.$q$),
  ($q$pd-583$q$, $q$math$q$, $q$Problem-Solving and Data Analysis$q$, $q$Inference from sample statistics$q$, 2, null, $q$A poll of a random sample of voters estimated that 54% support a proposal, with a margin of error of 2 percentage points. Which of the following is the most plausible range for the percent of all voters who support the proposal?$q$, $q$["50% to 54%","53% to 55%","52% to 56%","54% to 58%"]$q$::jsonb, 2, $q$The plausible range is the estimate plus or minus the margin of error: 52% to 56%.$q$),
  ($q$pd-584$q$, $q$math$q$, $q$Problem-Solving and Data Analysis$q$, $q$One-variable data$q$, 1, null, $q$The mean of 6 numbers is 49. When one of the numbers, 64, is removed, what is the mean of the remaining 5 numbers?$q$, $q$["34","46","49","48"]$q$::jsonb, 1, $q$The total is 6 × 49 = 294. Without 64, the total is 230, so the new mean is 230/5 = 46.$q$),
  ($q$pd-585$q$, $q$math$q$, $q$Problem-Solving and Data Analysis$q$, $q$One-variable data$q$, 1, null, $q$The mean of 5 numbers is 32. When one of the numbers, 44, is removed, what is the mean of the remaining 4 numbers?$q$, $q$["29","32","20","31"]$q$::jsonb, 0, $q$The total is 5 × 32 = 160. Without 44, the total is 116, so the new mean is 116/4 = 29.$q$),
  ($q$pd-586$q$, $q$math$q$, $q$Problem-Solving and Data Analysis$q$, $q$Conditional probability$q$, 2, null, $q$A survey asked 74 students whether they prefer online or in-person classes. Of the 44 first-year students, 12 prefer online classes. Of the 30 upper-year students, 14 prefer online classes. If a student who prefers online classes is chosen at random, what is the probability that the student is a first-year student?$q$, $q$["6/13","3/11","6/37","7/13"]$q$::jsonb, 0, $q$26 students prefer online classes, and 12 of them are first-year students, so the probability is 12/26 = 6/13.$q$),
  ($q$pd-587$q$, $q$math$q$, $q$Problem-Solving and Data Analysis$q$, $q$Ratios and proportions$q$, 1, null, $q$The ratio of red marbles to blue marbles in a bag is 5:4. If the bag contains 54 marbles in total, how many are red?$q$, $q$["10","24","30","35"]$q$::jsonb, 2, $q$There are 9 parts in total, so each part is 54/9 = 6 marbles. Red: 5 × 6 = 30.$q$),
  ($q$pd-588$q$, $q$math$q$, $q$Problem-Solving and Data Analysis$q$, $q$Two-variable data$q$, 2, null, $q$A line of best fit for a scatterplot is y = 4x + 50, where x is the number of employees and y is the monthly output. Which of the following is the best interpretation of the number 4 in this context?$q$, $q$["The number of employees is predicted to be 4 when the monthly output is 50.","When the number of employees is 0, the predicted monthly output is 4.","For each 1-unit increase in the number of employees, the predicted monthly output increases by 4.","The monthly output increases by 4 percent each time."]$q$::jsonb, 2, $q$The slope is the predicted change in y for each 1-unit increase in x.$q$),
  ($q$pd-589$q$, $q$math$q$, $q$Problem-Solving and Data Analysis$q$, $q$One-variable data$q$, 2, null, $q$The mean of 8 test scores is 62. After one more test score is added, the mean of all 9 scores is 64. What is the score that was added?$q$, $q$["80","88","71","78"]$q$::jsonb, 0, $q$The new total is 9 × 64 = 576; the old total was 8 × 62 = 496. The added score is 576 − 496 = 80.$q$),
  ($q$pd-590$q$, $q$math$q$, $q$Problem-Solving and Data Analysis$q$, $q$Rates and units$q$, 2, null, $q$One hose can fill a tank in 6 hours, and a second hose can fill the same tank in 3 hours. Working together, how many hours will the two hoses take to fill the tank?$q$, $q$["9","2","3","4.5"]$q$::jsonb, 1, $q$The combined rate is 1/6 + 1/3 = 9/18 of the tank per hour, so the time is 18/9 = 2 hours.$q$),
  ($q$pd-591$q$, $q$math$q$, $q$Problem-Solving and Data Analysis$q$, $q$Inference from sample statistics$q$, 2, null, $q$In a random sample of 400 students from a school of 2,000, 30% said they ride the bus. Based on this sample, which is the best estimate of the number of students at the school who ride the bus?$q$, $q$["12,000","600","240","700"]$q$::jsonb, 1, $q$30% of 2,000 = 600.$q$),
  ($q$pd-592$q$, $q$math$q$, $q$Problem-Solving and Data Analysis$q$, $q$Rates and units$q$, 1, null, $q$A pump fills a pool at a rate of 15 gallons per minute. How many minutes will it take to fill 240 gallons?$q$, $q$["225","8","3600","16"]$q$::jsonb, 3, $q$Time = 240 ÷ 15 = 16 minutes.$q$),
  ($q$pd-593$q$, $q$math$q$, $q$Problem-Solving and Data Analysis$q$, $q$Ratios and proportions$q$, 1, null, $q$The ratio of x to y is 5:3, and the ratio of y to z is 6:2. What is the ratio of x to z?$q$, $q$["15:2","5:2","5:1","7:4"]$q$::jsonb, 2, $q$x:y = 5:3 = 10:6. Since y:z = 6:2, matching the y-terms gives x:y:z = 10:6:2, so x:z = 10:2 = 5:1.$q$),
  ($q$pd-594$q$, $q$math$q$, $q$Problem-Solving and Data Analysis$q$, $q$Rates and units$q$, 2, null, $q$One hose can fill a tank in 20 hours, and a second hose can fill the same tank in 5 hours. Working together, how many hours will the two hoses take to fill the tank?$q$, $q$["4","15","25","12.5"]$q$::jsonb, 0, $q$The combined rate is 1/20 + 1/5 = 25/100 of the tank per hour, so the time is 100/25 = 4 hours.$q$),
  ($q$pd-595$q$, $q$math$q$, $q$Problem-Solving and Data Analysis$q$, $q$Percentages$q$, 1, null, $q$The price of a jacket decreased from $105 to $70. By what percent did the price decrease? (Round to the nearest whole percent.)$q$, $q$["43%","33%","50%","28%"]$q$::jsonb, 1, $q$Percent change = |70 − 105| / 105 × 100 = 35/105 × 100 ≈ 33%.$q$),
  ($q$pd-596$q$, $q$math$q$, $q$Problem-Solving and Data Analysis$q$, $q$One-variable data$q$, 2, null, $q$The mean of 7 test scores is 74. After one more test score is added, the mean of all 8 scores is 76. What is the score that was added?$q$, $q$["88","82","90","97"]$q$::jsonb, 2, $q$The new total is 8 × 76 = 608; the old total was 7 × 74 = 518. The added score is 608 − 518 = 90.$q$),
  ($q$pd-597$q$, $q$math$q$, $q$Problem-Solving and Data Analysis$q$, $q$Rates and units$q$, 2, null, $q$One hose can fill a tank in 6 hours, and a second hose can fill the same tank in 12 hours. Working together, how many hours will the two hoses take to fill the tank?$q$, $q$["4","6","18","9"]$q$::jsonb, 0, $q$The combined rate is 1/6 + 1/12 = 18/72 of the tank per hour, so the time is 72/18 = 4 hours.$q$),
  ($q$pd-598$q$, $q$math$q$, $q$Problem-Solving and Data Analysis$q$, $q$Percentages$q$, 1, null, $q$A price is increased by 30% and then the new price is decreased by 20%. The final price is what percent of the original price?$q$, $q$["104%","109%","95%","110%"]$q$::jsonb, 0, $q$The final price is 1.3 × 0.8 = 1.04 of the original, or 104%.$q$),
  ($q$pd-599$q$, $q$math$q$, $q$Problem-Solving and Data Analysis$q$, $q$Percentages$q$, 2, null, $q$A store discounts an item by 20%, and then takes an additional 25% off the discounted price. The two discounts together are equivalent to a single discount of what percent?$q$, $q$["22.5%","5%","40%","45%"]$q$::jsonb, 2, $q$The price becomes 0.8 × 0.75 = 0.6 of the original, which is a discount of 40%.$q$),
